#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MoveNodeArgs {
    pub id: Id,
    /// New parent (node or page); default the current one.
    #[serde(default)]
    pub parent_id: Option<Id>,
    /// Position in the parent's children after the node is taken out;
    /// default last when reparenting, unchanged otherwise.
    #[serde(default)]
    pub index: Option<usize>,
    /// New position relative to the parent.
    #[serde(default)]
    pub x: Option<f32>,
    #[serde(default)]
    pub y: Option<f32>,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DuplicateNodeArgs {
    pub id: Id,
    /// Default: the original's parent.
    #[serde(default)]
    pub parent_id: Option<Id>,
    /// Default: just above the original, or last in another parent.
    #[serde(default)]
    pub index: Option<usize>,
    /// Added to the copy's `x`, `y`; default `[0, 0]`.
    #[serde(default)]
    pub offset: Option<[f32; 2]>,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SetTokensArgs {
    /// `"color.primary": "#2563eb"`; `null` removes the token.
    #[serde(default)]
    pub colors: BTreeMap<String, Option<String>>,
    #[serde(default)]
    pub spacing: BTreeMap<String, Option<f32>>,
    #[serde(default)]
    pub radii: BTreeMap<String, Option<f32>>,
    #[serde(default)]
    pub fonts: BTreeMap<String, Option<String>>,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum StyleKindArg {
    Fill,
    Stroke,
    Text,
    Effect,
}

impl StyleKindArg {
    pub fn tag(self) -> &'static str {
        match self {
            StyleKindArg::Fill => "fill",
            StyleKindArg::Stroke => "stroke",
            StyleKindArg::Text => "text",
            StyleKindArg::Effect => "effect",
        }
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct UpsertStyleArgs {
    /// Update this style; without it a new style is created.
    #[serde(default)]
    pub id: Option<Id>,
    /// "Heading/H1"; '/' groups styles in the UI.
    pub name: String,
    pub kind: StyleKindArg,
    /// The kind's fields in file-format JSON: fill `{ fills }`, stroke
    /// `{ strokes, width }`, text `{ style }`, effect `{ shadows }`.
    pub value: JsonObject,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ApplyStyleArgs {
    pub node_ids: Vec<Id>,
    /// The style to apply, or `null` to detach (copy the style's values onto
    /// the nodes and clear the reference).
    pub style_id: Option<Id>,
    /// Which reference to set; default from the style's kind. With
    /// `style_id: null` and no slot, every style is detached.
    #[serde(default)]
    pub slot: Option<StyleKindArg>,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SetSelectionArgs {
    pub ids: Vec<Id>,
    /// Also scroll and zoom the canvas to the nodes.
    #[serde(default)]
    pub zoom_to: bool,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ScreenshotArgs {
    pub id: Id,
    #[serde(default = "one_f")]
    pub scale: f32,
    /// Longest side in pixels; the scale is reduced to fit.
    #[serde(default = "max_size")]
    pub max_size: u32,
    /// `#rrggbb[aa]` painted behind the node; default transparent.
    #[serde(default)]
    pub background: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ExportFormatArg {
    Png,
    Svg,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ExportFileArgs {
    pub id: Id,
    pub format: ExportFormatArg,
    /// Absolute, or relative to the document's directory. Must end in `.png`
    /// or `.svg` to match `format`, and be inside the document's directory
    /// or `$HOME` with no hidden folder or file below it.
    pub path: String,
    #[serde(default = "one_f")]
    pub scale: f32,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct CreateComponentArgs {
    /// The frame to turn into a component. It stays where it is, as an
    /// instance with the same ID.
    pub from_id: Id,
    /// The component's name, e.g. "Button/Primary"; default the frame's name.
    #[serde(default)]
    pub name: Option<String>,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct CreateInstanceArgs {
    pub component_id: Id,
    /// A node ID (a frame or group) or a page ID.
    pub parent_id: Id,
    /// Position among the parent's children (back to front); default last.
    #[serde(default)]
    pub index: Option<usize>,
    #[serde(default)]
    pub x: Option<f32>,
    #[serde(default)]
    pub y: Option<f32>,
    /// Overrides by the component node they apply to, as in the file format:
    /// `{ "<componentNodeId>": { "type": "text", "content": "Pay" } }`. Types:
    /// `text` (`content`), `fills` (`fills`), `visible` (`visible`) and
    /// `swap` (`component`).
    #[serde(default)]
    pub overrides: Option<JsonObject>,
    /// Select the new instance.
    #[serde(default)]
    pub select: bool,
    /// Fail with `stale_revision` unless the document is at this revision
    /// (from an earlier result or `get_document`).
    #[serde(default)]
    pub if_revision: Option<u64>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum CodeFormatArg {
    Html,
    Tailwind,
    React,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum TokenModeArg {
    CssVars,
    Inline,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, JsonSchema)]
pub enum TailwindArg {
    #[serde(rename = "v4")]
    V4,
    #[serde(rename = "v3")]
    V3,
}

#[derive(Debug, Default, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ExportCodeOptions {
    /// How token references are written; default `css_vars`.
    #[serde(default)]
    pub tokens: Option<TokenModeArg>,
    /// React: one file per component, instances call it. Default true.
    #[serde(default)]
    pub include_components: Option<bool>,
    /// The root takes the full width up to its design width. Default false.
    #[serde(default)]
    pub responsive: Option<bool>,
    /// Tailwind version for `tailwind` and `react`; default `v4`.
    #[serde(default)]
    pub tailwind: Option<TailwindArg>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ExportCodeArgs {
    pub id: Id,
    pub format: CodeFormatArg,
    #[serde(default)]
    pub options: ExportCodeOptions,
}

fn one() -> u32 {
    1
}
fn one_f() -> f32 {
    1.0
}
fn yes() -> bool {
    true
}
fn fifty() -> u32 {
    50
}
fn max_size() -> u32 {
    1600
}

// Document tools: headless mode only (`tessel mcp --headless`, §6.7).

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct OpenDocumentArgs {
    /// A `.tessel.json` file inside the workspace folder: relative to it, or
    /// absolute.
    pub path: String,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct NewDocumentArgs {
    /// Where to save it, ending in `.tessel.json`: relative to the workspace
    /// folder, or absolute inside it. Fails if the file exists.
    pub path: String,
    /// Start from a copy of this template (a `name` from list_documents'
    /// `templates`) instead of a blank frame. Then leave out width, height
    /// and background: the template has them.
    #[serde(default)]
    pub template: Option<String>,
    /// A blank design's size in px, e.g. 1080 x 1350 for a portrait social post.
    #[serde(default)]
    pub width: Option<f32>,
    #[serde(default)]
    pub height: Option<f32>,
    /// The document title; default the file name.
    #[serde(default)]
    pub title: Option<String>,
    /// A blank design frame's fill, `#rrggbb[aa]`; default white.
    #[serde(default)]
    pub background: Option<String>,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ImportImageArgs {
    /// A PNG, JPEG, GIF or WebP file inside the workspace folder or a folder
    /// the server was given with `--images`.
    pub path: String,
    /// Pixel art: a whole number from 2 to 12 that enlarges the image by that
    /// much with nearest neighbour, so every pixel stays a crisp square.
    /// Leave it out for photos.
    #[serde(default)]
    pub scale: Option<u32>,
}
